/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
        txb_ISU_NM.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS30900.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    $c.cm.PanelToGroupBox(panel_1);

    // 콤보 세팅.
    scwin.setCombo();

    // 기본값 세팅
    scwin.setDefaultVal();
    const array_grid = [grd_List];
    setResizeGrid(array_grid);
};

