/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnDblClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (colid === "ISU_NM" || colid === "STD_CD_APPL_ID") {
            let sStdCd = dts_List.getCellData(row, "STD_CD_APPL_ID"); // STD_CD_APPL_ID

            if (sStdCd !== "") {
                let KND = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_CD");
                let STD_CD = dts_List.getCellData(row, "STD_CD");
                // alert("STD_CD " +STD_CD);
                if (KND === "지표" || KND === "선물옵션" || KND === "스트립") {
                    txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
                } else {
                    txb_param1.setValue(dts_List.getCellData(row, "STD_CD_APPL_ID"));
                }
                txb_param2.setValue("R");
                fn_GetPar = scwin.getParam;
                ins_ViewIsuReqInfo(KND);
            }
        } else if (colid === "STD_CD") {
            let sStdCd = dts_List.getCellData(row, "STD_CD"); // 표준코드

            if (sStdCd !== "") {
                let KND = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_NM");
                const STD_CD_APPL_CONTN_TP_CD = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_CD");
                if (STD_CD_APPL_CONTN_TP_CD === "77") {
                    KND = "전자단기사채";
                }
                let STD_CD = dts_List.getCellData(row, "STD_CD");
                // alert("STD_CD " +STD_CD);
                if (KND === "지표" || KND === "선물옵션" || KND === "스트립") {
                    txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
                } else {
                    txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
                }
                txb_param2.setValue("");
                fn_GetPar = scwin.getParam;
                ins_ViewIsuMaster(KND, STD_CD);
            }
        } else if (colid === "COM_NM") {
            const isurcd = dts_List.getCellData(row, "ISUR_CD").substring(0, 1);
            if (isurcd === "#") return;
            txb_param1.setValue(dts_List.getCellData(row, "ISUR_CD")); // 발행기관 코드
            txb_param2.setValue(dts_List.getCellData(row, "COM_NM")); // 발행기관명
            fn_GetPar = scwin.getParam;
            ins_popupOpen("", "", "ULDINS91600", "발행기관 상세정보", "1190", "710");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS30900.grd_List_OnDblClick" });
    }
};

