/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDINS30900.xml", SCREN_PROCS_TP_CD_07, '');
        const today = $c.ut.cGetToday("yyyymmddhhmmss");
        const title = "표준코드처리내역";
        const xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";
        $c.data.downloadGridViewOffice(grd_List, title, xls_path, 8, 0);
        // grd_List.GridToExcel(title, "", "8");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS30900.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!await scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCombo
 * @description 콤보박스 만들기
 * @returns {void}
 * @hidden N
 */
scwin.setCombo = function() {
    ins_combo_set(dts_STD_CD_APPL_CONTN_TP_CD, "ULDINS30900.xml", SCREN_PROCS_TP_CD_01, "03425", "ALL"); // 상품구분
    ins_combo_set(dts_APPL_PROCS_TP_CD, "ULDINS30900.xml", SCREN_PROCS_TP_CD_01, "03398", "ALL"); // 처리구분

};

/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    const sToday = $c.ut.cGetToday2();
    edt_FROM_STD_CD_APPL_DD.setValue(sToday);
    edt_TO_STD_CD_APPL_DD.setValue(sToday);
    panel_5.hide();
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_List.removeAll();
    txb_TotalCnt.setValue("총 0건");
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function() {
    // 발행기관코드가 입력되면 기간조건 체크안함
    if (txb_ISUR_CD.getValue() === "") {
        // 날짜입력체크
        if (edt_FROM_STD_CD_APPL_DD.getValue() === "" && edt_TO_STD_CD_APPL_DD.getValue() === "" && edt_FROM_ACPT_PROCS_DD.getValue() === "" && edt_TO_ACPT_PROCS_DD.getValue() === "") {
            // 날짜입력이없으면
            await $c.win.alert("신청일 또는 처리일을 입력하세요.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        } else {
            if (edt_FROM_STD_CD_APPL_DD.getValue() !== "" || edt_TO_STD_CD_APPL_DD.getValue() !== "") {
                if (edt_FROM_STD_CD_APPL_DD.getValue() === "" || edt_TO_STD_CD_APPL_DD.getValue() === "") {
                    await $c.win.alert("신청일을 입력하세요.");
                    edt_FROM_STD_CD_APPL_DD.focus();
                    return false;
                }
            }
            if (edt_FROM_ACPT_PROCS_DD.getValue() !== "" || edt_TO_ACPT_PROCS_DD.getValue() !== "") {
                if (edt_FROM_ACPT_PROCS_DD.getValue() === "" || edt_TO_ACPT_PROCS_DD.getValue() === "") {
                    await $c.win.alert("처리일을 입력하세요.");
                    edt_FROM_ACPT_PROCS_DD.focus();
                    return false;
                }
            }
        }

        // 1년 이내 체크
        if ((edt_FROM_STD_CD_APPL_DD.getValue() !== "" && edt_TO_STD_CD_APPL_DD.getValue() !== "") &&
            Number($c.ut.cGetPlusYear(edt_FROM_STD_CD_APPL_DD.getValue(), 1)) < Number(edt_TO_STD_CD_APPL_DD.getValue())) {
            await $c.win.alert("신청일의 검색 기간은 1년 이내로만 가능합니다.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        }
        if ((edt_FROM_ACPT_PROCS_DD.getValue() !== "" && edt_TO_ACPT_PROCS_DD.getValue() !== "") &&
            Number($c.ut.cGetPlusYear(edt_FROM_ACPT_PROCS_DD.getValue(), 1)) < Number(edt_TO_ACPT_PROCS_DD.getValue())) {
            await $c.win.alert("처리일의 검색 기간은 1년 이내로만 가능합니다.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        }
    }

    // 신청일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_APPL_DD, edt_TO_STD_CD_APPL_DD) === false) {
        return false;
    }
    // 처리일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_ACPT_PROCS_DD, edt_TO_ACPT_PROCS_DD) === false) {
        return false;
    }
    return true;
};

